(()=>{
 const cs=getComputedStyle;
 const dlg=[...document.querySelectorAll('div')].find(d=>(d.getAttribute('style')||'').indexOf('width: 1320px')>=0);
 if(!dlg) return 'no';
 const sp=[...dlg.querySelectorAll('span')].filter(s=>cs(s).width==='34px'&&cs(s).borderRadius==='9px');
 if(!sp.length) return 'none';
 const k=sp[0].firstElementChild;
 const seg=[...dlg.querySelectorAll('div')].find(d=>cs(d).padding==='3px');
 return {track:[cs(sp[0]).width,cs(sp[0]).height,cs(sp[0]).borderRadius,cs(sp[0]).backgroundColor,cs(sp[0]).transition],
  knob:[cs(k).width,cs(k).height,cs(k).borderRadius,cs(k).left,cs(k).transition,cs(k).backgroundColor],
  seg:seg?[cs(seg).padding,cs(seg).gap,cs(seg).borderRadius,cs(seg).backgroundColor]:null};
})()

(()=>{
 const cs=getComputedStyle;
 const btns=[...document.querySelectorAll('main section button')].filter(b=>cs(b).width==='38px');
 const rowh=[...document.querySelectorAll('main section div')].filter(d=>cs(d).gridTemplateColumns&&/repeat\(4/.test(cs(d).gridTemplateColumns));
 const tel=[...document.querySelectorAll('main section div')].filter(d=>getComputedStyle(d).height==='150px');
 return {effortBtns:btns.map(b=>[cs(b).width,cs(b).height,cs(b).borderRadius,cs(b).borderColor,cs(b).color,cs(b).filter,cs(b).transition,cs(b).backgroundColor]),
  gridH:rowh.length?[cs(rowh[0]).height,cs(rowh[0]).gridTemplateColumns]:null,
  chartH:tel.length?[cs(tel[0]).height]:null};
})()

(()=>{
 const cs=getComputedStyle;
 const t=document.querySelector('main section');
 const ta=t.querySelector('textarea');
 const wrap=ta.parentElement;
 const bar=ta.nextElementSibling;
 const send=[...bar.querySelectorAll('button')].pop();
 const model=[...bar.querySelectorAll('button')][0];
 return {wrap:[cs(wrap).borderRadius,cs(wrap).borderTopWidth+' '+cs(wrap).borderTopColor,cs(wrap).backgroundColor,cs(wrap).position],
  ta:[cs(ta).fontSize,cs(ta).lineHeight,cs(ta).padding,cs(ta).width],
  bar:[cs(bar).padding,cs(bar).gap],
  attach:[cs(model).width,cs(model).height,cs(model).borderRadius,cs(model).backgroundColor],
  send:[cs(send).width,cs(send).height,cs(send).borderRadius,cs(send).backgroundColor,cs(send).color],
  sendWrap:[cs(wrap.parentElement).padding]};
})()
